// Monta, em ordem, todas as chamadas que o Airtable precisa receber.
// Um no HTTP so executa todas: o endereco e o metodo mudam por item.
const b = $json.body || {};
const BASE = 'https://api.airtable.com/v0/app6PyYmtFduIMp7B/';
const T = { entidades: 'tbl5Joji6gAir3mNh', locais: 'tblffVczCf1VeNxs7', contatos: 'tblXXOEOCwQnC2qFX' };

const texto = (v) => String(v ?? '').trim();
const lista = (v) => texto(v) || null;
const linhas = (v) => (Array.isArray(v) ? v.map(texto).filter(Boolean) : []);
const ids = (v) => String(v || '').split(',').map((x) => x.trim())
  .filter((x) => /^rec[A-Za-z0-9]{14}$/.test(x));

const entidadeId = ids(b.id)[0];
if (!entidadeId) throw new Error('Pedido sem o codigo do cadastro.');

const lerJson = (t) => {
  try { const v = JSON.parse(t || '[]'); return Array.isArray(v) ? v : []; }
  catch (erro) { return []; }
};

// O Airtable aceita no maximo 10 registros por chamada.
const emLotes = (arr) => {
  const lotes = [];
  for (let i = 0; i < arr.length; i += 10) lotes.push(arr.slice(i, i + 10));
  return lotes;
};

const chamadas = [];
const gravar = (tabela, registros, novo) => {
  for (const lote of emLotes(registros)) {
    chamadas.push({
      metodo: novo ? 'POST' : 'PATCH',
      url: BASE + tabela,
      corpo: { typecast: true, records: lote },
    });
  }
};
const apagar = (tabela, lista) => {
  for (const lote of emLotes(lista)) {
    chamadas.push({
      metodo: 'DELETE',
      url: BASE + tabela + '?' + lote.map((id) => 'records[]=' + id).join('&'),
      corpo: null,
    });
  }
};

// ---- 1. o cadastro em si ----
chamadas.push({
  metodo: 'PATCH',
  url: BASE + T.entidades,
  corpo: { typecast: true, records: [{ id: entidadeId, fields: {
    CPF_CNPJ: texto(b.documento).replace(/\D/g, ''),
    Razao_Social_Nome: texto(b.razaoSocial),
    Nome_Fantasia_Identificador: texto(b.nomeFantasia),
    Tipo_Documento: lista(b.tipo),
    Exigencia_Fiscal: lista(b.exigenciaFiscal),
    Emails_Financeiro_NFE: texto(b.emails),
    WhatsApp_CNPJ: texto(b.whatsappCnpj),
    Administradora: texto(b.administradora),
    Empresa_Sindicos: texto(b.empresaSindicos),
    Status: lista(b.status) || 'Ativo',
    Observacoes: texto(b.observacoes),
  } }] },
});

// ---- 2. enderecos ----
const locais = lerJson(b.locais)
  .map((l) => ({
    id: ids(l.id)[0] || null,
    nome: texto(l.nome), endereco: texto(l.endereco),
    bairroCidade: texto(l.bairroCidade), acesso: texto(l.acesso),
  }))
  .filter((l) => l.nome || l.endereco || l.bairroCidade || l.acesso);

const camposLocal = (l) => ({
  Nome_do_Local: l.nome || l.endereco || 'Local sem nome',
  Endereco_Completo: l.endereco,
  Bairro_Cidade: l.bairroCidade,
  Observacoes_Acesso: l.acesso,
});

gravar(T.locais, locais.filter((l) => l.id).map((l) => ({ id: l.id, fields: camposLocal(l) })), false);
gravar(T.locais, locais.filter((l) => !l.id).map((l) => ({
  fields: { ...camposLocal(l), Cliente_Vinculado: [entidadeId], Status: 'Ativo' },
})), true);
apagar(T.locais, ids(b.locaisApagar));

// ---- 3. contatos ----
const contatos = lerJson(b.contatos)
  .map((c) => ({
    id: ids(c.id)[0] || null,
    nome: texto(c.nome), cargo: texto(c.cargo),
    whatsapps: linhas(c.whatsapps), emails: linhas(c.emails),
    observacoes: texto(c.observacoes),
  }))
  .filter((c) => c.nome || c.whatsapps.length || c.emails.length || c.observacoes);

const camposContato = (c) => ({
  Nome_Contato: c.nome || c.whatsapps[0] || c.emails[0] || 'Contato sem nome',
  Cargo_Funcao: c.cargo || null,
  WhatsApps: c.whatsapps.join('\n'),
  Emails: c.emails.join('\n'),
  Observacoes: c.observacoes,
});

gravar(T.contatos, contatos.filter((c) => c.id).map((c) => ({ id: c.id, fields: camposContato(c) })), false);
gravar(T.contatos, contatos.filter((c) => !c.id).map((c) => ({
  fields: { ...camposContato(c), Entidades_Vinculadas: [entidadeId], Status: 'Ativo' },
})), true);
apagar(T.contatos, ids(b.contatosApagar));

return chamadas.map((c) => ({ json: c }));

